# EVOLVE-BLOCK-START
from typing import Tuple, List
import numpy as np
import pandas as pd
from solver import Algorithm


class Evolved(Algorithm):
    """Lossless bounded optimizer for character-prefix reuse."""

    def __init__(self, df: pd.DataFrame = None):
        """Store the optional source dataframe and initialize shape metadata."""
        self.df = df
        self.num_rows = 0
        self.num_cols = 0

    @staticmethod
    def _cell_text(value) -> str:
        """Serialize a scalar as scoring does, converting scalar missing values to ''. """
        try:
            missing = pd.isna(value)
            if isinstance(missing, (bool, np.bool_)) and bool(missing):
                return ""
        except Exception:
            pass
        return str(value)

    @staticmethod
    def _lcp(left: str, right: str) -> int:
        """Compute exact LCP length using binary-searched C-level slice comparisons."""
        low = 0
        high = min(len(left), len(right))
        while low < high:
            middle = (low + high + 1) // 2
            if left[:middle] == right[:middle]:
                low = middle
            else:
                high = middle - 1
        return low

    @classmethod
    def _trie_score(cls, strings: List[str]) -> int:
        """Return exact ideal Trie reuse from sorted adjacent serialized strings."""
        if len(strings) < 2:
            return 0

        ordered = sorted(strings)
        total = 0
        previous = ordered[0]

        for current in ordered[1:]:
            if current == previous:
                total += len(current)
            else:
                total += cls._lcp(previous, current)
            previous = current

        return total

    @staticmethod
    def _make_strings(cells, orders) -> List[str]:
        """Serialize each source row using its row-specific column permutation."""
        return [
            "".join(cells[row, column] for column in orders[row])
            for row in range(cells.shape[0])
        ]

    @staticmethod
    def _repeat_mass(values) -> int:
        """Return length-weighted ordered-pair repetition for one column."""
        counts = {}
        lengths = {}

        for value in values:
            counts[value] = counts.get(value, 0) + 1
            if value not in lengths:
                lengths[value] = len(value)

        return sum(
            lengths[value] * count * (count - 1)
            for value, count in counts.items()
        )

    def _frequency_order(self, cells) -> List[int]:
        """Rank every column by independent length-weighted value repetition."""
        _, columns = cells.shape
        ranked = [
            (self._repeat_mass(cells[:, column]), column)
            for column in range(columns)
        ]
        ranked.sort(key=lambda item: (-item[0], item[1]))
        return [column for _, column in ranked]

    def _cooccurrence_order(self, cells) -> List[int]:
        """Build a bounded endpoint-grown graph-seriation column ordering."""
        rows, columns = cells.shape

        if columns <= 1:
            return list(range(columns))

        masses = [
            (self._repeat_mass(cells[:, column]), column)
            for column in range(columns)
        ]
        masses.sort(key=lambda item: (-item[0], item[1]))

        # Restrict the quadratic graph to the most promising columns.
        active = [
            column
            for mass, column in masses[:min(48, columns)]
            if mass > 0
        ]

        if len(active) <= 1:
            return [column for _, column in masses]

        size = len(active)
        affinity = np.zeros((size, size), dtype=np.int64)

        # For each pair, count repeated row-wise value pairs.  The shorter
        # value length approximates the amount of stable textual prefix.
        for left_index in range(size):
            left_column = active[left_index]
            left_values = cells[:, left_column]

            for right_index in range(left_index + 1, size):
                right_column = active[right_index]
                pair_counts = {}

                for row in range(rows):
                    key = (left_values[row], cells[row, right_column])
                    pair_counts[key] = pair_counts.get(key, 0) + 1

                score = 0
                for (left_value, right_value), count in pair_counts.items():
                    if count > 1:
                        score += (
                            min(len(left_value), len(right_value))
                            * count * (count - 1)
                        )

                affinity[left_index, right_index] = score
                affinity[right_index, left_index] = score

        # Select the strongest deterministic starting edge.
        best = None
        for left in range(size):
            for right in range(left + 1, size):
                choice = (
                    int(affinity[left, right]),
                    -active[left],
                    -active[right],
                )
                if best is None or choice > best[0]:
                    best = (choice, left, right)

        if best is None or best[0][0] <= 0:
            return [column for _, column in masses]

        _, first, second = best
        chain = [first, second]
        unused = set(range(size))
        unused.remove(first)
        unused.remove(second)

        # Repeatedly attach the best remaining vertex to either endpoint.
        while unused:
            selected = None

            for candidate in unused:
                left_score = int(affinity[candidate, chain[0]])
                right_score = int(affinity[candidate, chain[-1]])

                if left_score >= right_score:
                    option = (
                        left_score,
                        -active[candidate],
                        0,
                        candidate,
                    )
                else:
                    option = (
                        right_score,
                        -active[candidate],
                        -1,
                        candidate,
                    )

                if selected is None or option > selected[0]:
                    selected = (option, candidate)

            option, candidate = selected
            if option[2] == 0:
                chain.insert(0, candidate)
            else:
                chain.append(candidate)
            unused.remove(candidate)

        ordered_active = [active[index] for index in chain]
        active_set = set(ordered_active)

        # Preserve deterministic independent ranking for the graph tail.
        tail = [
            column for _, column in masses
            if column not in active_set
        ]
        return ordered_active + tail

    @classmethod
    def _group_score(cls, cells, rows, order) -> int:
        """Score one group using the exact sorted serialized-string objective."""
        values = [
            "".join(cells[row, column] for column in order)
            for row in rows
        ]

        if len(values) < 2:
            return 0

        values.sort()
        total = 0
        previous = values[0]

        for current in values[1:]:
            if current == previous:
                total += len(current)
            else:
                total += cls._lcp(previous, current)
            previous = current

        return total

    def _refine_leaf(self, cells, rows, order) -> List[int]:
        """Perform two bounded adjacent-swap passes on a conditional suffix."""
        if len(order) < 2 or len(rows) < 2:
            return list(order)

        current = list(order)
        score = self._group_score(cells, rows, current)
        limit = min(12, len(current) - 1)

        for reverse in (False, True):
            positions = (
                range(limit - 1, -1, -1)
                if reverse else range(limit)
            )

            for position in positions:
                trial = current[:]
                trial[position], trial[position + 1] = (
                    trial[position + 1],
                    trial[position],
                )
                trial_score = self._group_score(cells, rows, trial)

                if trial_score > score:
                    current = trial
                    score = trial_score

        return current

    def _conditional_orders(self, cells) -> List[List[int]]:
        """Partition rows by the strongest repeated field and rank each suffix."""
        rows, columns = cells.shape

        if columns <= 1:
            return [list(range(columns)) for _ in range(rows)]

        lead = max(
            range(columns),
            key=lambda column: (
                self._repeat_mass(cells[:, column]),
                -column,
            ),
        )

        groups = {}
        for row in range(rows):
            groups.setdefault(cells[row, lead], []).append(row)

        remaining = [
            column for column in range(columns)
            if column != lead
        ]
        result = [None] * rows

        for group_rows in groups.values():
            ranked = [
                (
                    self._repeat_mass(cells[group_rows, column]),
                    column,
                )
                for column in remaining
            ]
            ranked.sort(key=lambda item: (-item[0], item[1]))

            suffix = self._refine_leaf(
                cells,
                group_rows,
                [column for _, column in ranked],
            )
            full_order = [lead] + suffix

            for row in group_rows:
                result[row] = full_order[:]

        return result

    @classmethod
    def _candidate(cls, cells, orders):
        """Serialize, score, and lexicographically order one candidate."""
        strings = cls._make_strings(cells, orders)
        score = cls._trie_score(strings)
        row_order = sorted(
            range(len(strings)),
            key=lambda row: (strings[row], row),
        )
        return score, row_order

    def reorder(
        self,
        df: pd.DataFrame,
        early_stop: int = 0,
        row_stop: int = None,
        col_stop: int = None,
        col_merge=[],
        one_way_dep=[],
        distinct_value_threshold=0.8,
        parallel=True,
    ) -> Tuple[pd.DataFrame, List[List[str]]]:
        """Choose the best of frequency, co-occurrence, and conditional orders."""
        rows, columns = df.shape
        self.num_rows = rows
        self.num_cols = columns

        if rows == 0 or columns == 0:
            return df.copy(), [[] for _ in range(rows)]

        raw = df.to_numpy(dtype=object, copy=True)
        cells = np.empty((rows, columns), dtype=object)

        for row in range(rows):
            for column in range(columns):
                cells[row, column] = self._cell_text(raw[row, column])

        frequency = self._frequency_order(cells)
        cooccurrence = self._cooccurrence_order(cells)
        conditional = self._conditional_orders(cells)

        candidates = [
            [frequency[:] for _ in range(rows)],
            [cooccurrence[:] for _ in range(rows)],
            conditional,
        ]

        best_choice = None
        best_row_order = None
        best_orders = None

        for orders in candidates:
            score, row_order = self._candidate(cells, orders)
            signature = tuple(orders[0]) if orders else ()
            choice = (score, tuple(-column for column in signature))

            if best_choice is None or choice > best_choice:
                best_choice = choice
                best_row_order = row_order
                best_orders = orders

        output = np.empty((rows, columns), dtype=object)
        output_orders = []

        for destination, source in enumerate(best_row_order):
            permutation = best_orders[source]
            output[destination, :] = [
                raw[source, column]
                for column in permutation
            ]
            output_orders.append([
                df.columns[column]
                for column in permutation
            ])

        result = pd.DataFrame(output, columns=df.columns)
        return result, output_orders


