        self,
        df: pd.DataFrame,
        early_stop: int = 0,
        row_stop: int = None,
        col_stop: int = None,
        col_merge=[],
        one_way_dep=[],
        distinct_value_threshold=0.8,
        parallel=True,
    ) -> Tuple[pd.DataFrame, List[List[str]]]:
        """Evaluate two global orders and one refined conditional order losslessly."""
        n, m = df.shape
        self.num_rows = n
        self.num_cols = m

        if n == 0 or m == 0:
            return df.copy(), [[] for _ in range(n)]

